def test_all_non_severity_questions_labeled_as_proxy_not_official_intent(self):
    out=evaluate()
    for x in out["records"]:
        if x["source_question_intent"] in ("discharge","surgery","travel_for_treatment","recovery"):
            self.assertEqual(x["template_intent"],"severity")
            self.assertNotEqual(x["source_question_intent"],x["template_intent"])

def test_blocked_roles_never_disguised_as_self(self):
    x={q["family_id"]:q for q in evaluate()["records"]}
    for family in ("kaiwu.health.19980616.hen_illness",
                   "kaiwu.health.19980621.rooster_illness",
                   "kaiwu.final.recovery",
                   "shenqi.health.19971227.spouse_travel_for_treatment"):
        self.assertEqual(x[family]["status"],"blocked_unverified_role_or_chart")
        self.assertNotIn("readout",x[family])

def test_existing_two_real_histories_preserve_original_v31_wording(self):
    sealed=json.loads((ROOT/"data/evaluation/health_v32/two_new_source_families_V31_READOUTS_SEALED.json").read_text("utf8"))
    x={q["family_id"]:q for q in evaluate()["records"]}
    for old in sealed["samples"]:
        new=x[old["family_id"]]
        self.assertEqual(new["status"],"rendered_v31")
        self.assertEqual(new["readout"],old["text"])
        self.assertEqual(new["readout_sha256"],old["text_sha256"])

def test_print_all_changed_hour_prose(self):
   for x in evaluate()["samples"]:
       print("V31_HOUR_"+x["case_id"]+"="+next(s["text"] for s in x["sections"] if s["id"]=="08_hour"))
       print("V31_SHA_"+x["case_id"]+"="+x["sha256"])

def test_four_other_health_subdomains_remain_unreviewed(self):
    old=run()
    cal={"year_ganzhi":"丙午","month_ganzhi":"戊戌","day_ganzhi":"戊辰","hour_ganzhi":"庚申"}
    for intent in ("treatment","discharge","surgery","travel_for_treatment"):
        with self.assertRaises(ValueError):
            analyze_health_severity_v26(chart=old["test_receipt"]["chart"],
                inquiry={"intent":intent,"relationship":"self","consultation_context":"direct_self"},
                calendar=cal,db_path=PARENT_DB)

def test_print_unedited_real_offline_user_output(self):
    x=run()
    print("\nWENGUA_REAL_GENGSHEN_V26_BEGIN")
    for i,section in enumerate(x["sections"],1):
        print("SECTION_%02d "%i+section["title"]+"："+section["text"])
    print("AUDIT="+json.dumps({
        "verdict":x["audit"]["tradition_binary_verdict"],
        "fuyin_fanyin":x["audit"]["fuyin_fanyin"],
        "inner_outer":[x["audit"]["illness_inner_outer"],x["audit"]["patient_inner_outer"]],
        "source_name":x["audit"]["pair_original_still_auditable"]["name"],
        "production_type":x["audit"]["render_mode"]
    },ensure_ascii=False))
    print("WENGUA_REAL_GENGSHEN_V26_END")

