def test_print_verbatim_timing_and_monthly_templates(self):
    for i,x in enumerate(evaluate()["samples"],1):
        print("V29_MEDICAL_CASE_%d_BEGIN"%i)
        for s in x["sections"]:
            if s["id"] in ("07_medicine","08_hour","09_hazards","10_pace","11_final"):
                print(s["title"]+"："+s["text"])
        print("V29_CASE_SHA="+x["sha256"])
        print("V29_MEDICAL_CASE_%d_END"%i)

def test_severity_only_do_not_change_other_intents(self):
    r=evaluate()
    for x in r["samples"]:
        self.assertEqual(x["live_engine"],"analyze_health_severity_v31")
    self.assertTrue(r["pure_python_no_gpt"])

def test_door_matching_attested_three_wonders_and_jade(self):
   for v in evaluate()["samples"]:
      q={z["id"]:z for z in v["corrected_17_composite_predicates"]}
      for x in ("health_composite_07","health_composite_08"):
         self.assertIn(q[x]["state"],("triggered","not_triggered"))
         self.assertNotIn("unknown",q[x]["state"])
         if q[x]["state"]=="triggered":
             self.assertTrue(q[x]["evidence"])
      self.assertEqual(q["health_composite_07"]["source"],"kaiwu_ch04_section_三奇得使")

def test_print_runtime_two_cases_for_manual_review(self):
    x=evaluate()
    print("\nV28_HISTORICAL_MEDICAL_OPPORTUNITY_START")
    for i,r in enumerate(x["new_predictions"],1):
        print(f"CASE_{i}_ID="+r["case_id"])
        print(f"CASE_{i}_SHA="+r["new_readout_sha256"])
        for j,s in enumerate(r["sections"],1):
            print(f"CASE_{i}_SECTION_{j:02d} "+s["title"]+"："+s["text"])
    print("V28_HISTORICAL_MEDICAL_OPPORTUNITY_END")
